css:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background-color: #f0f0f0;
  font-family: Arial, sans-serif;
}

#pdf_container {
  /* A4 size: 210mm x 297mm at 96 DPI = 794px x 1123px */
  width: 100%;
  min-height: 297mm;
  background: white;
  box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.1);
  border: 1px solid #000;
  padding: 15mm 5mm 15mm 5mm;
  position: relative;
}

/* Print styles for A4 */
@media print {
  body {
    background: white;
  }

  #pdf_container {
    width: 100%;
    height: 297mm;
    margin: 0;
    padding: 15mm 20mm;
    box-shadow: none;
    border: 1px solid #000;
    page-break-after: always;
  }

  #mark {
    display: none; /* Hide instructions when printing */
  }
}

#pdf_container #mark {
  text-align: center;
  font-family: "Trirong", serif;
  margin: 0 0 15px 0;
  font-size: 14px;
}

header {
  display: flex !important;
  align-items: center;
  justify-content: space-between; /* Add this */
  gap: 15px; /* Add spacing between items */
  margin-bottom: 20px;
}


header div img {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  object-fit: cover;
}

header div h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 3px;
}

header div h4 {
  font-size: 14px;
  font-weight: 500;
  margin-bottom: 3px;
}

header div small {
  font-size: 12px;
}

header div h3,
header div h4,
header div small {
  display: block;
  text-align: center;
  font-family: 'Abel', sans-serif;
  padding: 2px 0;
}

header .text {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  flex: 1;
}

#info {
  text-align: center;
  margin: 15px 0;
}

#info .framer_sc {
  background-color: #c0bbbb77;
  padding: 5px 0;
  margin: 10px 0;
  font-size: 16px;
}

#info h3 {
  margin: 10px 0;
  font-size: 16px;
}

#form {
  margin: 15px 0;
}

#form h4 {
  text-align: center;
  background-color: #c0bbbb77;
  padding: 5px 0;
  font-size: 14px;
  margin-bottom: 10px;
}

#user_form {
  display: flex !important;
  justify-content: space-between;
  gap: 0px;
}

#first_col,
#second_col {
  flex: 1;
  min-width: 300px;
}

#first_col .details,
#second_col .details {

  display: flex;
  align-items: left;
}

.details {
  display: flex;
  font-size: 13px;
}

.details .label {
  width: 120px;
  display:flex;
  align-items:center;
  text-align: left;
  font-weight: 600;
}

.details .input {
  flex: 1;
   display:flex;
  align-items:center;
}

.details .input span {
  display: inline-block;
  padding: 2px 0;
}

#table1,
#table2 {
  width: 100%;
  overflow-x: auto;
  margin: 15px 0;
}

#table1 th,
#table2 th {
  background-color: #c0bbbb77;
  font-family: 'Abel', sans-serif;
  font-weight: 600;
  font-size: 12px;
}

#table1 table,
#table1 th,
#table1 td,
#table2 table,
#table2 th,
#table2 td {
  border: 1px solid black;
  border-collapse: collapse;
  text-align: center;
  padding: 5px;
  font-size: 11px;
}

#table1 table,
#table2 table {
  width: 100%;
  table-layout: auto;
}

#table1 tbody td,
#table2 tbody td {
  min-height: 25px;
}

#ul {
  margin: 30px 0;
}

#ul ul {
  list-style-type: none;
  display: flex;
  width: 100%;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

#ul ul li {
  flex: 1;
  text-align: center;
  font-size: 12px;
  font-weight: 600;
  min-width: 120px;
}

footer {
  border: 1px solid gray;
  margin: 15px 0 0 0;
  padding: 10px;
}

footer p {
  margin-bottom: 5px;
  font-size: 13px;
}

footer ul {
  list-style-type: disc;
  padding-left: 20px;
}

footer ul li {
  margin: 3px 0;
}

footer ul li small {
  font-size: 11px;
  line-height: 1.4;
}
